import Foundation

/// 从实战录屏提取的牌面模板，由工具脚本生成，不要手改。
/// 点数顺序同 Rank.allCases，花色顺序同 Suit.allCases。
enum GlyphTemplates {
    static let rankWidth = 32
    static let rankHeight = 44
    static let suitWidth = 32
    static let suitHeight = 32
    static let ranks = [UInt8](Data(base64Encoded: "")!)
    static let suits = [UInt8](Data(base64Encoded: "")!)
}
